@theme {
  --color-wyp-canvas: #ede6df;
  --color-wyp-hero: #f5efeb;
  --color-wyp-surface-tint: #e5ddd4;
  --color-wyp-card: #ffffff;
  --color-wyp-card-subtle: #faf8f5;

  --color-wyp-obsidian: #121417;
  --color-wyp-charcoal: #2b2f38;
  --color-wyp-slate: #666e7d;

  --color-wyp-sage: #d8eadf;
  --color-wyp-sky: #dbe8fa;
  --color-wyp-apricot: #fce8dc;
  --color-wyp-lavender: #ece6f6;
  --color-wyp-colophon: #16181d;

  --font-display: var(--font-jakarta), system-ui, sans-serif;
  --font-body: var(--font-jakarta), system-ui, sans-serif;

  --ease-out: cubic-bezier(0.23, 1, 0.32, 1);
  --ease-in-out: cubic-bezier(0.77, 0, 0.175, 1);
  --ease-smooth: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-spring: cubic-bezier(0.34, 1.56, 0.64, 1);
}

/* A calm field guide, built on the original Waypoint paper palette. */
.wyp-page {
  --wyp-paper: #f5efeb;
  --wyp-line: #d8d0c5;
  --wyp-muted: #666e7d;
  --wyp-ink: #121417;
  --wyp-ease: cubic-bezier(0.23, 1, 0.32, 1);
  font-size: 14px;
}
.wyp-page main {
  overflow: clip;
}
.wyp-page * {
  box-sizing: border-box;
}
.wyp-page h1,
.wyp-page h2,
.wyp-page h3 {
  text-wrap: balance;
}
.wyp-page p {
  text-wrap: pretty;
}
.wyp-page button,
.wyp-page a {
  -webkit-tap-highlight-color: transparent;
}
.wyp-page button {
  cursor: pointer;
  transition: transform 160ms var(--ease-out);
}
.wyp-page button:active,
.wyp-button:active {
  transform: scale(0.97);
}
.wyp-page :focus-visible {
  outline: 2px solid #1e4f94;
  outline-offset: 5px;
}
.wyp-page [id] {
  scroll-margin-top: 110px;
}
.wyp-container {
  width: min(1200px, calc(100% - 96px));
  margin-inline: auto;
}
.wyp-chapter {
  padding-block: 144px;
}
.wyp-kicker {
  display: flex;
  align-items: center;
  gap: 8px;
  color: #535964;
  font-size: 12px;
  font-weight: 500;
  margin-bottom: 24px;
}
.wyp-page .wyp-chapter h2 {
  font-size: clamp(36px, 4.2vw, 60px);
  font-weight: 500;
  letter-spacing: -0.055em;
  line-height: 1.08;
}
.wyp-text-link {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  font-size: 13px;
  font-weight: 600;
  padding-block: 8px;
}
.wyp-text-link svg {
  transition: transform 0.4s var(--wyp-ease);
}
.wyp-text-link:hover svg {
  transform: translate(3px, -3px);
}
.wyp-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 24px;
  border-radius: 8px;
  padding: 16px 24px;
  min-height: 52px;
  font-size: 13px;
  font-weight: 600;
  transition:
    background 0.2s ease,
    box-shadow 0.2s ease,
    transform 160ms var(--ease-out);
}
.wyp-button-dark {
  background: #121417;
  color: #f5efeb;
}
.wyp-button-dark:hover {
  background: #2b2f38;
  box-shadow: 0 4px 16px #12141715;
}
.wyp-button-light {
  background: #faf8f5dd;
  color: #121417;
  border: 1px solid #d8d0c5;
}
.wyp-button-light:hover {
  background: #fff;
}
.wyp-status-dot {
  display: inline-block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #216143;
  flex-shrink: 0;
}
.wyp-skip-link {
  position: fixed;
  left: 24px;
  top: -80px;
  z-index: 100;
  background: #121417;
  color: #fff;
  padding: 16px;
  border-radius: 8px;
}
.wyp-skip-link:focus {
  top: 12px;
}

/* Landscape, split-line entrance, and a working planar flight deck. */
.wyp-hero {
  position: relative;
  padding: 164px 0 64px;
  background: #f5efeb;
  isolation: isolate;
}
.wyp-hero-landscape {
  position: absolute;
  z-index: -1;
  inset: 0 0 0;
  background: url("/templates/waypoint/hero-bg-1920.webp") center 40% / cover
    no-repeat;
  opacity: 0.64;
  mask-image: linear-gradient(#0009, #000 62%, transparent 98%);
  pointer-events: none;
}
.wyp-hero-copy {
  text-align: center;
}
.wyp-hero-intro {
  font-size: 12px;
  margin-bottom: 28px;
  color: #535964;
}
.wyp-hero h1 {
  font-size: clamp(48px, 6.2vw, 88px);
  letter-spacing: -0.065em;
  font-weight: 500;
  line-height: 1.08;
  margin: 0 auto 28px;
}
.wyp-line {
  display: block;
  overflow: hidden;
  padding-bottom: 0.08em;
  margin-bottom: -0.08em;
}
.wyp-line > span {
  display: block;
}
.wyp-hero-description {
  max-width: 510px;
  margin: 0 auto;
  font-size: 16px;
  line-height: 1.8;
  color: #2b2f38;
}
.wyp-hero-actions {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-top: 32px;
}
.wyp-hero-deck {
  position: relative;
  margin-top: 80px;
  max-width: 1104px;
}
.wyp-deck-caption {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 11px;
  color: #535964;
  margin: 0 4px 16px;
}
.wyp-deck-caption > span:last-child {
  display: flex;
  align-items: center;
  gap: 10px;
}
.wyp-dashboard {
  padding: 24px;
  border-radius: 14px;
  background: #faf8f5;
  border: 1px solid #d8d0c5;
  box-shadow: 0 20px 70px -30px #69534545;
  text-align: left;
}
.wyp-dashboard-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding-bottom: 24px;
}
.wyp-dashboard-title {
  display: flex;
  gap: 12px;
  align-items: center;
  font-size: 12px;
}
.wyp-dashboard-title > span {
  color: #666e7d;
  font-size: 11px;
}
.wyp-dashboard-title svg {
  color: #8a3e1b;
}
.wyp-reset {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  padding: 8px 12px;
  border: 1px solid #d8d0c5;
  border-radius: 6px;
  transition: background 0.3s;
}
.wyp-reset:hover {
  background: #ede6df;
}
.wyp-board-columns {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}
.wyp-board-column {
  min-width: 0;
  padding: 12px;
  background: #ede6df80;
  border-radius: 8px;
  min-height: 280px;
}
.wyp-column-heading {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 10px;
  margin-bottom: 16px;
}
.wyp-column-heading strong {
  font-weight: 600;
}
.wyp-column-heading > span:nth-last-child(2) {
  font-family: var(--font-jetbrains), monospace;
  color: #666e7d;
}
.wyp-column-heading svg {
  margin-left: auto;
}
.wyp-stage-dot {
  height: 6px;
  width: 6px;
  border: 1px solid #666e7d;
  border-radius: 50%;
}
.wyp-stage-1 {
  background: #dbe8fa;
  border-color: #1e4f94;
}
.wyp-stage-2 {
  background: #fce8dc;
  border-color: #8a3e1b;
}
.wyp-stage-3 {
  background: #d8eadf;
  border-color: #216143;
}
.wyp-column-cards {
  display: grid;
  gap: 8px;
}
.wyp-company-card {
  background: #fff;
  border: 1px solid #d8d0c580;
  border-radius: 6px;
  text-align: left;
  padding: 16px 12px 12px;
  width: 100%;
  transition:
    transform 0.4s var(--wyp-ease),
    box-shadow 0.4s;
}
.wyp-company-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 6px 12px #69534512;
}
.wyp-company-mark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  background: #ece6f6;
  color: #4b3878;
  border-radius: 6px;
  font-weight: 600;
  font-size: 13px;
  flex-shrink: 0;
}
.wyp-mark-anthropic {
  background: #e5ddd4;
  color: #121417;
}
.wyp-mark-vercel {
  background: #121417;
  color: #fff;
}
.wyp-mark-figma {
  background: #fce8dc;
  color: #8a3e1b;
}
.wyp-mark-stripe {
  background: #dbe8fa;
  color: #1e4f94;
}
.wyp-company-card > strong {
  display: block;
  margin-top: 12px;
  font-size: 12px;
  font-weight: 600;
}
.wyp-company-card p {
  font-size: 10px;
  color: #535964;
  margin-top: 4px;
}
.wyp-card-contact {
  display: block;
  color: #666e7d;
  font-size: 9px;
  margin-top: 12px;
}
.wyp-card-highlight {
  display: inline-block;
  font-size: 9px;
  margin-top: 12px;
  padding: 4px 6px;
  background: #d8eadf;
  color: #216143;
  border-radius: 3px;
}
.wyp-card-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 9px;
  color: #666e7d;
  border-top: 1px solid #ede6df;
  margin-top: 12px;
  padding-top: 8px;
}
.wyp-empty-column {
  padding: 24px 4px;
  font-size: 11px;
  line-height: 1.7;
  color: #666e7d;
}
.wyp-board-footer {
  display: flex;
  justify-content: space-between;
  padding-top: 20px;
  gap: 12px;
  font-size: 9px;
  color: #666e7d;
}
.wyp-board-footer > span:first-child {
  display: flex;
  align-items: center;
  gap: 6px;
}
.wyp-horizon {
  margin: 64px auto 0;
  width: 1px;
  height: 80px;
  background: #d8d0c5;
  position: relative;
}
.wyp-horizon span {
  position: absolute;
  width: 7px;
  height: 7px;
  border: 1px solid #8a3e1b;
  background: #f5efeb;
  border-radius: 50%;
  left: -3px;
  top: 0;
}

/* Wide product panorama. All text is real DOM, backed by the supplied contour art. */
.wyp-panorama {
  background: #f5efeb;
  padding-top: 48px;
}
.wyp-panorama-heading,
.wyp-lab-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 48px;
  margin-bottom: 56px;
}
.wyp-panorama-heading > p,
.wyp-lab-heading > p {
  font-size: 14px;
  line-height: 1.9;
  color: #535964;
  width: 300px;
  padding-bottom: 4px;
}
.wyp-panorama-heading .wyp-text-link {
  margin-top: 16px;
  color: #121417;
}
.wyp-panorama-artboard {
  padding: 56px;
  border-radius: 16px;
  background: #e5ddd4
    url("/templates/waypoint/waypoint-08-topographic-background-1600.webp")
    center / cover;
}
.wyp-tiny {
  font-size: 10px;
  color: #666e7d;
  font-weight: 500;
}
.wyp-panorama-caption {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  color: #666e7d;
  font-size: 10px;
  margin-top: 20px;
}

/* A measured four-stop route. GSAP pins only on sufficiently tall desktop screens. */
.wyp-story {
  background: #ede6df;
}
.wyp-editorial-heading {
  display: grid;
  grid-template-columns: 1fr 1fr;
  column-gap: 48px;
  align-items: end;
  margin-bottom: 80px;
}
.wyp-editorial-heading .wyp-kicker {
  grid-column: 1/-1;
}
.wyp-editorial-heading > p:last-child {
  justify-self: end;
  font-size: 14px;
  line-height: 1.9;
  width: 300px;
  color: #535964;
}
.wyp-story-body {
  display: grid;
  grid-template-columns: 0.85fr 1.3fr;
  column-gap: 96px;
  align-items: start;
}
.wyp-story-step {
  min-height: 68vh;
  padding: 48px 0 120px 32px;
  position: relative;
  border-left: 1px solid #d8d0c5;
}
.wyp-story-step:last-child {
  min-height: 600px;
  padding-bottom: 200px;
}
.wyp-story-step-button {
  display: flex;
  align-items: center;
  gap: 16px;
  width: 100%;
  text-align: left;
  color: #666e7d;
  font-size: 12px;
  margin-bottom: 32px;
}
.wyp-story-step-button > svg {
  margin-left: auto;
}
.wyp-route-marker {
  width: 32px;
  height: 32px;
  border: 1px solid #d8d0c5;
  background: #ede6df;
  border-radius: 50%;
  font-family: var(--font-jetbrains), monospace;
  font-size: 9px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-left: -49px;
  transition:
    background 0.4s,
    color 0.4s;
}
.is-active .wyp-route-marker {
  background: #121417;
  color: #fff;
  border-color: #121417;
}
.wyp-story-step h3 {
  font-size: 32px;
  font-weight: 500;
  line-height: 1.15;
  letter-spacing: -0.05em;
  margin-bottom: 24px;
}
.wyp-story-step > p {
  font-size: 14px;
  line-height: 1.85;
  color: #535964;
  max-width: 320px;
}
.wyp-story-step > a {
  margin-top: 24px;
}
.wyp-mobile-story-visual {
  display: none;
}
.wyp-story-canvas {
  width: 100%;
  min-height: 500px;
  border-radius: 12px;
  background: #e5ddd4
    url("/templates/waypoint/waypoint-08-topographic-background-800.webp")
    center / cover;
  padding: 24px;
}
.wyp-canvas-label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 9px;
  color: #535964;
  margin-bottom: 24px;
}
.wyp-canvas-label > span:last-child {
  font-family: var(--font-jetbrains), monospace;
}
.wyp-story-visual-frame {
  position: relative;
  min-height: 385px;
}
.wyp-story-visual {
  position: absolute;
  inset: 0;
  opacity: 0;
  visibility: hidden;
  transform: translateX(12px);
  clip-path: inset(0 0 0 6%);
  transition:
    opacity 280ms var(--ease-out),
    transform 320ms var(--ease-out),
    clip-path 320ms var(--ease-out),
    visibility 280ms;
}
.wyp-story-visual.is-active {
  opacity: 1;
  visibility: visible;
  transform: none;
  clip-path: inset(0);
}
.wyp-story-progress {
  display: flex;
  gap: 8px;
  margin: 24px auto 12px;
  width: min(340px, 100%);
}
.wyp-story-progress button {
  flex: 1;
  height: 36px;
  min-width: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px;
  border: 1px solid #d8d0c580;
  border-radius: 4px;
  transition:
    flex 0.45s var(--wyp-ease),
    background 0.3s;
}
.wyp-story-progress button > span:first-child {
  display: block;
  background: #faf8f5;
  border-radius: 4px;
  height: 3px;
  width: 16px;
  flex-shrink: 0;
  transition: background 0.4s;
}
.wyp-story-progress button > span.is-complete {
  background: #8a3e1b;
}
.wyp-progress-label {
  max-width: 0;
  overflow: hidden;
  opacity: 0;
  font-size: 9px;
  white-space: nowrap;
  transition: opacity 0.3s;
}
.wyp-story-progress button:hover,
.wyp-story-progress button:focus-visible,
.wyp-story-progress button[aria-pressed="true"] {
  flex: 2.4;
  background: #faf8f5a0;
}
.wyp-story-progress
  button:is(:hover, :focus-visible, [aria-pressed="true"])
  .wyp-progress-label {
  max-width: 80px;
  opacity: 1;
}
.wyp-canvas-footnote {
  font-size: 9px;
  text-align: center;
  color: #535964;
}

/* Existing functional widgets, with optional keyboard-controlled focus. */
.wyp-lab {
  background: #f5efeb;
}
.wyp-lab-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding-block: 16px;
  border-block: 1px solid #d8d0c5;
  margin-bottom: 32px;
}
.wyp-lab-tabs {
  display: flex;
  align-items: center;
  gap: 8px;
}
.wyp-lab-tabs > button {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  padding: 12px 16px;
  border-radius: 6px;
  transition:
    background 0.16s ease,
    color 0.16s ease,
    transform 160ms var(--ease-out);
}
.wyp-lab-tabs > button:hover {
  background: #ede6df;
}
.wyp-lab-tabs > button[aria-selected="true"] {
  background: #121417;
  color: #f5efeb;
}
.wyp-all-tools {
  border: 1px solid #d8d0c5;
  padding: 10px 16px;
  border-radius: 6px;
  font-size: 11px;
  white-space: nowrap;
}
.wyp-all-tools.is-active {
  background: #ede6df;
}
.wyp-lab-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  grid-auto-flow: dense;
  gap: 20px;
}
.wyp-lab-card {
  background: #fff;
  padding: 32px;
  border: 1px solid #d8d0c5;
  border-radius: 10px;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 32px;
}
.wyp-lab-card[hidden] {
  display: none;
}
.wyp-lab-card > div:last-child {
  margin-top: auto;
  min-width: 0;
}
.wyp-lab-grid.is-focused {
  grid-template-columns: 1fr;
}
.is-focused .wyp-lab-card {
  display: grid;
  grid-template-columns: 0.8fr 1.2fr;
  gap: 64px;
  align-items: center;
}
.is-focused .wyp-lab-card[hidden] {
  display: none;
}
.wyp-tool-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border: 1px solid #d8d0c5;
  border-radius: 8px;
  margin-bottom: 24px;
}
.wyp-lab-card h3 {
  font-size: 24px;
  font-weight: 500;
  letter-spacing: -0.04em;
}
.wyp-lab-card-copy > p {
  color: #666e7d;
  font-size: 12px;
  line-height: 1.8;
  margin-top: 12px;
  max-width: 340px;
}
.wyp-lab-disclaimer {
  font-size: 10px;
  color: #666e7d;
  margin-top: 24px;
}

/* Paper trail: a drawn route, stacked sheets, and manually selected context. */
.wyp-paper-trail {
  background: #ede6df;
}
.wyp-page .wyp-statement {
  font-size: clamp(40px, 5.8vw, 80px);
  max-width: 1100px;
  line-height: 1.13;
  letter-spacing: -0.06em;
  margin-bottom: 64px;
}
.wyp-inline-landscape {
  display: inline-block;
  vertical-align: middle;
  margin-left: 12px;
  width: 120px;
  height: 52px;
  border-radius: 50px;
  background: url("/templates/waypoint/hero-bg-1920.webp") 25% 65% / 240%;
  border: 1px solid #d8d0c5;
}
.wyp-paper-layout {
  display: grid;
  grid-template-columns: 0.85fr 1fr;
  gap: 120px;
  align-items: center;
}
.wyp-paper-intro {
  font-size: 14px;
  color: #535964;
  line-height: 1.9;
  max-width: 360px;
}
.wyp-timeline {
  position: relative;
  margin-top: 40px;
}
.wyp-timeline-line {
  position: absolute;
  left: 15px;
  top: 30px;
  bottom: 30px;
  width: 1px;
  background: #d8d0c5;
}
.wyp-timeline-line span {
  display: block;
  width: 100%;
  height: 100%;
  background: #8a3e1b;
}
.wyp-timeline-moment {
  position: relative;
  width: 100%;
  display: flex;
  align-items: center;
  gap: 24px;
  padding-block: 16px;
  text-align: left;
}
.wyp-timeline-moment > span {
  display: grid;
  place-items: center;
  background: #ede6df;
  border: 1px solid #d8d0c5;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  font-family: var(--font-jetbrains), monospace;
  font-size: 9px;
  transition:
    background 0.3s,
    color 0.3s;
}
.wyp-timeline-moment.is-selected > span {
  background: #121417;
  border-color: #121417;
  color: #fff;
}
.wyp-timeline-moment strong {
  display: block;
