.wyp-journal-entry > p:not(.wyp-tiny) {
  font-size: 13px;
  color: #535964;
  line-height: 1.9;
}
.wyp-journal-next {
  border-top: 1px solid #d8d0c5;
  padding-top: 20px;
  margin-top: 24px;
}
.wyp-journal-next p {
  font-size: 12px;
  line-height: 1.8;
  margin-top: 8px;
}
.wyp-journal-controls {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-top: 1px solid #e5ddd4;
  padding-top: 24px;
  margin-top: 24px;
  gap: 12px;
