}
.wyp-journal-controls button {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  border: 1px solid #d8d0c5;
  border-radius: 50%;
  transition: background 0.3s;
}
.wyp-journal-controls button:hover {
  background: #ede6df;
}
@keyframes wyp-note-in {
  from {
    opacity: 0.25;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

