}
.wyp-dialog {
  background: #faf8f5;
  border: 1px solid #d8d0c5;
  border-radius: 12px;
  padding: 40px;
  width: min(520px, calc(100% - 32px));
  max-height: calc(100dvh - 48px);
  overflow-y: auto;
  margin: auto;
  box-shadow: 0 24px 96px #12141740;
  color: #121417;
  opacity: 0;
  transform: scale(0.96);
  transition:
    opacity 220ms var(--ease-out),
    transform 220ms var(--ease-out),
    overlay 220ms var(--ease-out) allow-discrete,
    display 220ms var(--ease-out) allow-discrete;
}
.wyp-dialog[open] {
  opacity: 1;
  transform: scale(1);
}
@starting-style {
  .wyp-dialog[open] {
    opacity: 0;
    transform: scale(0.96);
  }
}
.wyp-dialog::backdrop {
  background: #12141766;
  backdrop-filter: blur(8px);
  opacity: 0;
  transition:
    opacity 220ms var(--ease-out),
    overlay 220ms var(--ease-out) allow-discrete,
    display 220ms var(--ease-out) allow-discrete;
}
.wyp-dialog[open]::backdrop {
  opacity: 1;
}
@starting-style {
  .wyp-dialog[open]::backdrop {
    opacity: 0;
  }
}
.wyp-dialog-close {
  position: absolute;
  top: 16px;
  right: 16px;
  padding: 8px;
}
.wyp-dialog h2 {
  font-size: 30px;
  line-height: 1.2;
  font-weight: 500;
  letter-spacing: -0.05em;
  padding-right: 16px;
}
.wyp-dialog h3 {
  margin-top: 24px;
  font-size: 20px;
}
