  font-size: 13px;
  color: #535964;
  line-height: 1.8;
  margin-block: 20px;
}
.wyp-dialog form {
  margin-top: 24px;
}
.wyp-dialog label {
  display: block;
  font-size: 11px;
  font-weight: 600;
  margin-block: 16px 8px;
}
.wyp-dialog input {
  width: 100%;
  background: #fff;
  border: 1px solid #d8d0c5;
  border-radius: 6px;
  padding: 12px 16px;
  font-size: 13px;
}
.wyp-dialog .wyp-button {
  margin-top: 24px;
  width: 100%;
}
.wyp-dialog small {
  display: block;
  font-size: 10px;
  color: #666e7d;
  margin-top: 20px;
}
.wyp-dialog [role="alert"] {
  color: #8a3e1b !important;
}

