/* Base resets & typography */
.wyp-body {
  font-family: var(--font-body);
  background-color: var(--color-wyp-canvas);
  color: var(--color-wyp-obsidian);
  min-height: 100vh;
}

/* Supplied ZIP artboards are preserved as full, flat images. */
.wyp-supplied-artwork {
  display: block;
  width: 100%;
  height: auto;
}
.wyp-hero-artwork {
  overflow: hidden;
  border-radius: 10px;
}
.wyp-hero-artwork figcaption {
  padding-top: 16px;
  font-size: 10px;
  color: #666e7d;
  text-align: center;
}
.wyp-page .wyp-panorama-artboard {
  padding: 0;
  overflow: hidden;
  background: #e5ddd4;
}
.wyp-gallery-frame {
  position: relative;
  aspect-ratio: 2752 / 1536;
}
.wyp-gallery-image {
  position: absolute;
  inset: 0;
  visibility: hidden;
  opacity: 0;
  clip-path: inset(0 0 0 4%);
  transition:
    opacity 280ms var(--ease-out),
    clip-path 320ms var(--ease-out),
    visibility 280ms;
}
.wyp-gallery-image.is-active {
  visibility: visible;
  opacity: 1;
  clip-path: inset(0);
}
.wyp-artwork-gallery-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 24px;
}
.wyp-artwork-gallery-tabs button {
  padding: 12px 16px;
  border: 1px solid #d8d0c5;
  border-radius: 6px;
  font-size: 11px;
  transition:
    background 0.16s ease,
    color 0.16s ease,
    border-color 0.16s ease,
    transform 160ms var(--ease-out);
}
.wyp-artwork-gallery-tabs button[aria-pressed="true"] {
  background: #121417;
  color: #f5efeb;
  border-color: #121417;
}
.wyp-artwork-gallery-tabs button:hover {
  background: #e5ddd4;
  color: #121417;
}
.wyp-gallery-caption {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
  padding-top: 24px;
}
.wyp-gallery-caption h3 {
  font-size: 20px;
  font-weight: 500;
  letter-spacing: -0.035em;
}
.wyp-gallery-caption p {
  font-size: 12px;
  color: #666e7d;
  line-height: 1.8;
  margin-top: 8px;
}
.wyp-gallery-controls {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-shrink: 0;
}
.wyp-gallery-controls button {
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  border: 1px solid #d8d0c5;
  border-radius: 50%;
  transition: background 0.3s;
}
.wyp-gallery-controls button:hover {
  background: #e5ddd4;
}
.wyp-gallery-controls > span {
  font-family: var(--font-jetbrains), monospace;
  font-size: 10px;
  color: #666e7d;
}
.wyp-artwork-note {
  color: #666e7d;
  font-size: 10px;
  line-height: 1.8;
  margin-top: 24px;
}
.wyp-page .wyp-story-canvas {
  padding: 0;
  background: transparent;
  min-height: 0;
}
.wyp-story-visual-frame {
  min-height: 0;
  aspect-ratio: 2752 / 1536;
  overflow: hidden;
  border-radius: 8px;
}
.wyp-story-visual .wyp-supplied-artwork {
