.wyp-mobile-nav {
  position: fixed;
  inset: 0;
  width: 100vw;
  height: 100dvh;
  max-width: none;
  max-height: none;
  margin: 0;
  padding: 24px;
  border: 0;
  background: #f5efeb;
  color: #121417;
  opacity: 0;
  transform: translateY(-8px);
  transition:
    opacity 240ms var(--ease-out),
    transform 240ms var(--ease-out),
    overlay 240ms var(--ease-out) allow-discrete,
    display 240ms var(--ease-out) allow-discrete;
}
.wyp-mobile-nav[open] {
  opacity: 1;
  transform: translateY(0);
}
@starting-style {
  .wyp-mobile-nav[open] {
    opacity: 0;
    transform: translateY(-8px);
  }
}
.wyp-mobile-nav::backdrop {
  background: #12141750;
  opacity: 0;
  transition:
    opacity 240ms var(--ease-out),
    overlay 240ms var(--ease-out) allow-discrete,
    display 240ms var(--ease-out) allow-discrete;
}
.wyp-mobile-nav[open]::backdrop {
  opacity: 1;
}
@starting-style {
  .wyp-mobile-nav[open]::backdrop {
    opacity: 0;
  }
}
.wyp-mobile-nav-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.wyp-mobile-nav-header button {
  padding: 12px;
}
.wyp-mobile-nav nav {
  display: flex;
  flex-direction: column;
  gap: 24px;
  padding-block: 64px;
}
.wyp-mobile-nav nav a {
  font-size: 32px;
  letter-spacing: -0.05em;
  animation: wyp-note-in 0.45s var(--ease-smooth) both;
}
.wyp-mobile-nav-actions {
  display: grid;
  gap: 24px;
  text-align: center;
}

/* Odometer rolling animation support */
.wyp-odometer-wheel {
  display: inline-flex;
  flex-direction: column;
  overflow: hidden;
  height: 1em;
  line-height: 1;
}

.wyp-odometer-strip {
  transition: transform 260ms var(--ease-out);
}

/* Tactile micro-transitions for Bento widgets */
@keyframes wyp-card-advance {
  from {
    opacity: 0.35;
    transform: translateX(-6px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.wyp-kanban-card-enter {
  animation: wyp-card-advance 200ms var(--ease-out) both;
}

@keyframes wyp-fade-blur {
  from {
    opacity: 0.5;
    filter: blur(1.5px);
    transform: translateY(2px);
  }
  to {
    opacity: 1;
    filter: blur(0);
    transform: none;
  }
}

.wyp-schedule-crossfade {
  animation: wyp-fade-blur 180ms var(--ease-out) both;
}

/* Accessible reduced-motion overrides: eliminate motion/transforms, preserve feedback */
@media (prefers-reduced-motion: reduce) {
  *,
  ::before,
  ::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
  }

  [data-parallax],
  [data-hero-line],
  .wyp-hero-deck,
  .wyp-hero-landscape,
  .wpv-outline,
  .wyp-odometer-strip {
    transform: none !important;
    animation: none !important;
    transition: none !important;
  }
}


/* ===================================================================
   WAYPOINT / EDITORIAL INTERLUDE: A CONSIDERED WAY FORWARD / 03 — 04
   =================================================================== */
#wpv-interlude {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background: #171c1c;
  color: #f3ede5;
  min-height: 100svh;
  display: flex;
  align-items: center;
  padding: 145px max(5vw, 24px);
  border-block: 1px solid #302b28;
}

#wpv-interlude:before {
  content: "";
  position: absolute;
  z-index: -2;
  inset: 0;
  background:
    radial-gradient(ellipse 48% 70% at 77% 52%, rgba(115, 88, 72, 0.24), transparent 72%),
    radial-gradient(ellipse 50% 70% at 0% 100%, rgba(143, 117, 101, 0.17), transparent 80%),
    linear-gradient(120deg, #171919, #23201e);
}

#wpv-interlude:after {
  content: "";
  position: absolute;
  z-index: -1;
  inset: 0;
  pointer-events: none;
  background-image: repeating-linear-gradient(0deg, rgba(255, 255, 255, 0.07) 0, rgba(255, 255, 255, 0.07) 1px, transparent 1px, transparent 78px);
  mask-image: linear-gradient(90deg, transparent, #000 40%, transparent);
  opacity: 0.14;
}

.wpv-interlude-wrap {
  width: min(100%, 1320px);
  margin: auto;
  display: grid;
  grid-template-columns: 1fr 0.82fr;
  align-items: center;
  gap: clamp(35px, 6vw, 115px);
  position: relative;
  z-index: 2;
}

.wpv-interlude-overline {
  font-family: var(--font-jetbrains), monospace;
  font-weight: 600;
  font-size: 11px;
  letter-spacing: 0.19em;
  color: #c6a989;
  text-transform: uppercase;
  margin: 0 0 42px;
}

.wpv-interlude-title {
  font-family: var(--font-jakarta), var(--font-display), sans-serif;
  font-size: clamp(64px, 8vw, 150px);
  line-height: 0.88;
  letter-spacing: -0.092em;
  max-width: 850px;
  font-weight: 720;
  margin: 0;
}

.wpv-interlude-title span {
  display: block;
}

.wpv-interlude-title .wpv-title-tan {
  color: #d9b591;
  font-weight: 550;
}

.wpv-interlude-sub {
  max-width: 430px;
  color: #c3b5aa;
  font-size: clamp(15px, 1.15vw, 18px);
  line-height: 1.9;
  margin: 43px 0 35px;
}

.wpv-interlude-link {
  color: #ede6df;
  display: inline-flex;
  align-items: center;
  gap: 22px;
  text-transform: uppercase;
  letter-spacing: 0.13em;
  font-family: var(--font-jetbrains), monospace;
  font-size: 11px;
  font-weight: 600;
  border-bottom: 1px solid #b99a7c;
  padding-bottom: 13px;
  transition: color 0.2s ease;
  text-decoration: none;
}

.wpv-interlude-link [aria-hidden="true"] {
  display: inline-block;
  transition: transform 200ms var(--ease-out);
}

.wpv-interlude-link:hover {
  color: #f1cfae;
}

.wpv-interlude-link:hover [aria-hidden="true"] {
  transform: translate(6px, -6px);
}

.wpv-interlude-map {
  position: relative;
  aspect-ratio: 1 / 1.06;
  width: 100%;
  display: grid;
  place-items: center;
}

.wpv-interlude-map > svg {
  width: 105%;
  height: 105%;
  overflow: visible;
  filter: drop-shadow(0 0 38px rgba(206, 169, 133, 0.08));
}

.wpv-interlude-map .wpv-route-base {
  stroke: rgba(187, 155, 128, 0.44);
  stroke-dasharray: 3 10;
  stroke-width: 1.8;
  fill: none;
}

.wpv-interlude-map .wpv-route-active {
  stroke: #e7c39d;
  stroke-width: 3;
  fill: none;
  stroke-linecap: round;
  filter: drop-shadow(0 0 7px rgba(240, 205, 160, 0.62));
}

.wpv-interlude-map .wpv-route-mapring {
  stroke: rgba(182, 153, 122, 0.17);
  stroke-width: 1;
  fill: none;
}

#wpv-route-dot {
  fill: #f2d9b5;
  stroke: #ffffff;
  stroke-width: 2;
  filter: drop-shadow(0 0 12px #e8ba8c);
}

.wpv-route-label {
  font-family: var(--font-jetbrains), monospace;
  font-weight: 600;
  font-size: 10px;
  fill: #cfbaa6;
  letter-spacing: 0.12em;
}

.wpv-map-hud {
  position: absolute;
  left: 0;
  bottom: 0;
  display: flex;
  gap: 15px;
  align-items: center;
  color: #bcaa98;
  font-family: var(--font-jetbrains), monospace;
  font-weight: 600;
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.wpv-map-hud .wpv-hud-line {
  height: 1px;
  width: 65px;
  background: #d1b08c;
}

.wpv-interlude-corner {
  position: absolute;
  right: 35px;
  top: 35px;
  color: #bda48b;
  font-family: var(--font-jetbrains), monospace;
  font-weight: 600;
  font-size: 10px;
  letter-spacing: 0.18em;
}

.wpv-interlude-counter {
  position: absolute;
  right: 35px;
  bottom: 35px;
  color: #d5b591;
  font-family: var(--font-jetbrains), monospace;
  font-weight: 600;
  font-size: 10px;
  letter-spacing: 0.14em;
}

/* Right side chapter reader HUD (matches screenshot 04 / 08 | A NEW DIRECTION) */
.wpv-interlude-chapter-hud {
  position: absolute;
  right: 20px;
  top: 50%;
  transform: translateY(-50%);
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 12px;
  pointer-events: none;
  z-index: 10;
}

.wpv-interlude-chapter-hud .wpv-interlude-chapter-index {
  font-family: var(--font-jetbrains), monospace;
  font-weight: 600;
  font-size: 10px;
  color: #a88d75;
  font-variant-numeric: tabular-nums;
}

.wpv-interlude-chapter-hud .wpv-interlude-chapter-bar {
  height: 80px;
  width: 1px;
  background: rgba(156, 134, 122, 0.3);
  position: relative;
  overflow: hidden;
}

.wpv-interlude-chapter-hud .wpv-interlude-chapter-bar span {
  position: absolute;
  top: 0;
  width: 100%;
  height: 35%;
  background: #c6a989;
}

.wpv-interlude-chapter-hud .wpv-interlude-chapter-name {
  font-family: var(--font-jetbrains), monospace;
  font-weight: 600;
  font-size: 9px;
  line-height: 1.5;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: #a88d75;
  writing-mode: vertical-rl;
  transform: rotate(180deg);
}

#wpv-interlude .wpv-outline {
  position: absolute;
  z-index: 0;
  font-size: clamp(100px, 18vw, 340px);
  font-weight: 800;
  letter-spacing: -0.09em;
  bottom: -0.41em;
  left: -0.03em;
  color: transparent;
  -webkit-text-stroke: 1px rgba(238, 220, 200, 0.08);
  white-space: nowrap;
  pointer-events: none;
  will-change: transform;
  animation: wpvOutline 24s ease-in-out infinite alternate;
}

@keyframes wpvOutline {
  from {
    transform: translateX(-2%);
  }
  to {
    transform: translateX(2%);
  }
}

@media (max-width: 1024px) {
  .wpv-interlude-wrap {
    grid-template-columns: 1fr 0.85fr;
  }
}

@media (max-width: 860px) {
  #wpv-interlude {
    min-height: 0;
