    display: none;
  }
}

@media (max-width: 640px) {
  .wpv-interlude-title {
    font-size: clamp(60px, 14vw, 94px);
  }
  .wpv-interlude-sub {
    margin-top: 25px;
  }
  #wpv-interlude {
    padding: 95px 22px 120px;
  }
  .wpv-interlude-corner {
    right: 20px;
    top: 22px;
    font-size: 8px;
  }
  .wpv-interlude-map {
    aspect-ratio: 1;
  }
  .wpv-map-hud {
    bottom: -4px;
  }
  #wpv-route-dot {
    filter: none;
  }
}

